import pytest


def age_at(born: int, now: int) -> int:
    """Whole years elapsed from birth year `born` to current year `now`.

    The result is `now - born`. The current year is passed in; the clock
    is never read. Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_age_typical() -> None:
    assert age_at(1990, 2026) == 36


def test_age_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_one_year() -> None:
    assert age_at(1999, 2000) == 1


def test_age_across_century() -> None:
    assert age_at(1899, 2001) == 102


def test_age_is_deterministic_for_same_inputs() -> None:
    assert age_at(1985, 2020) == age_at(1985, 2020)


def test_age_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)


def test_age_far_future_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(3000, 2026)

